int kvm_set_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state->mutex);
    kvm->pit_state->hpet = ps->hpet;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i].state = ps->channels[i];
        kvm->pit_set_count(kvm, i, ps->channels[i].count);
    }
    mutex_unlock(&kvm->pit_state->mutex);

    return 0;
}

int kvm_set_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state_mutex);
    kvm->pit_legacy_hpet = ps->flags & KVM_PIT_FLAGS_HPET_LEGACY;
    for (i = 0; i < 3; i++)
        kvm->pit_state[i] = ps->channels[i];
    kvm->pit.flags = ps->flags;
    for (i = 0; i < 3; i++)
        kvm_pit_load_count(kvm, i, ps->channels[i].count);
    mutex_unlock(&kvm->pit_state_mutex);

    return 0;
}

int kvm_pit_set_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state->pit_mutex);
    kvm->pit_state->legacy_hpet = ps->legacy_hpet;
    memcpy(kvm->pit_state->channels, ps->channels,
           sizeof(ps->channels));
    kvm->pit_state->flags = ps->flags;
    for (i = 0; i < 3; i++)
        kvm_pit_load_count(kvm->pit_state, i, ps->channels[i].count);

    mutex_unlock(&kvm->pit_state->pit_mutex);
    return 0;
}
